#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_bf16_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kBFloat16,
        name, " must have bfloat16 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. Per definition.json:
//   attn_output    : [batch_size, seq_len, hidden_size]   bf16
//   residual       : [batch_size, seq_len, hidden_size]   bf16
//   o_proj_weight  : [hidden_size, hidden_size]           bf16
//   output (DPS)   : [batch_size, seq_len, hidden_size]   bf16
//
// hidden_size is constant at 2560 per definition.json (Jamba-3B).
// Algorithm: output = (attn_output @ o_proj_weight.T) + residual.
void run(
    const torch::Tensor& attn_output,
    const torch::Tensor& residual,
    const torch::Tensor& o_proj_weight,
    torch::Tensor output
) {
    TORCH_CHECK(attn_output.dim() == 3,
                "attn_output must be 3D [B, S, H]; got ",
                attn_output.dim(), "D");
    TORCH_CHECK(residual.dim() == 3, "residual must be 3D");
    TORCH_CHECK(o_proj_weight.dim() == 2,
                "o_proj_weight must be 2D [H, H]");
    TORCH_CHECK(output.dim() == 3, "output must be 3D");

    const int64_t hidden_size = attn_output.size(2);
    TORCH_CHECK(hidden_size == 2560,
                "hidden_size must be 2560 for problem_030, got ",
                hidden_size);
    TORCH_CHECK(o_proj_weight.size(0) == hidden_size &&
                o_proj_weight.size(1) == hidden_size,
                "o_proj_weight must be [hidden_size, hidden_size]");
    TORCH_CHECK(residual.sizes() == attn_output.sizes(),
                "residual must share shape with attn_output");
    TORCH_CHECK(output.sizes() == attn_output.sizes(),
                "output must share shape with attn_output");

    check_bf16_contiguous_cuda(attn_output, "attn_output");
    check_bf16_contiguous_cuda(residual, "residual");
    check_bf16_contiguous_cuda(o_proj_weight, "o_proj_weight");
    check_bf16_contiguous_cuda(output, "output");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_030_attn_output_proj_residual_launcher(
        attn_output, residual, o_proj_weight, output, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "BF16 fused attention output projection (`(attn @ "
        "o_proj_weight.T) + residual`) via CUTLASS TensorOp on "
        "Sm80; residual passed as the GEMM's C source so the "
        "epilogue adds it in-place; destination-passing style.");
}

#include "kernel.h"

#include <cutlass/gemm/device/gemm.h>
#include <cutlass/numeric_types.h>
#include <cutlass/layout/matrix.h>
#include <cutlass/arch/arch.h>
#include <cutlass/arch/mma.h>

// BF16 fused attention output projection + residual add:
//   output = (attn_output @ o_proj_weight.T) + residual
//
// Layout encoding:
//   attn_output: [B, S, H] row-major  →  flatten to [B*S, H];
//                describe as RowMajor with lda = H.
//   o_proj_weight: [H, H] row-major; we want `attn_output @ o_proj_weight.T`
//                which is equivalent to viewing o_proj_weight as
//                ColumnMajor with ldb = H. Same trick the fp16 GEMM
//                landings use to fuse the .T into the layout.
//   residual: [B, S, H] row-major  →  flatten to [B*S, H];
//             describe as RowMajor with ldc = H. Passed as the
//             GEMM's C source.
//   output: [B, S, H] row-major  →  flatten to [B*S, H];
//           describe as RowMajor with ldd = H. The GEMM's D
//           destination. Same buffer as the eval driver allocates
//           in DPS; the kernel writes to it in-place.
//
// The CUTLASS epilogue `LinearCombination` computes
//   D[i, j] = α · accumulator[i, j] + β · C[i, j]
// with α = 1.0 and β = 1.0, which is exactly the residual-add we
// need. No separate elementwise add kernel; the residual sectors
// stream through the epilogue alongside the GEMM output.
//
// We pick Sm80 TensorOp (same template family as the existing fp16
// GEMM landings) so the same code path compiles for both the local
// 3090 Ti (sm_86) and the Phase-2 B200 (sm_100a) target — Sm80 PTX
// is preserved by both. ThreadblockShape 128x128x32 / WarpShape
// 64x64x32 / InstructionShape 16x8x16 / NumStages 3 is the standard
// Ampere BF16 fp32-accumulator GEMM tile.

namespace {

using ElementInputA = cutlass::bfloat16_t;
using ElementInputB = cutlass::bfloat16_t;
using ElementOutput = cutlass::bfloat16_t;
using ElementAccumulator = float;

using LayoutInputA = cutlass::layout::RowMajor;
using LayoutInputB = cutlass::layout::ColumnMajor;
using LayoutOutput = cutlass::layout::RowMajor;

using MMAOp = cutlass::arch::OpClassTensorOp;
using SmArch = cutlass::arch::Sm80;

using ThreadblockShape = cutlass::gemm::GemmShape<128, 128, 32>;
using WarpShape = cutlass::gemm::GemmShape<64, 64, 32>;
using InstructionShape = cutlass::gemm::GemmShape<16, 8, 16>;

using EpilogueOp = cutlass::epilogue::thread::LinearCombination<
    ElementOutput,
    128 / cutlass::sizeof_bits<ElementOutput>::value,
    ElementAccumulator,
    ElementAccumulator>;

using SwizzleThreadBlock =
    cutlass::gemm::threadblock::GemmIdentityThreadblockSwizzle<>;
constexpr int NumStages = 3;

using CutlassGemm = cutlass::gemm::device::Gemm<
    ElementInputA, LayoutInputA,
    ElementInputB, LayoutInputB,
    ElementOutput, LayoutOutput,
    ElementAccumulator,
    MMAOp,
    SmArch,
    ThreadblockShape,
    WarpShape,
    InstructionShape,
    EpilogueOp,
    SwizzleThreadBlock,
    NumStages>;

}  // namespace

void problem_030_attn_output_proj_residual_launcher(
    const torch::Tensor& attn_output,
    const torch::Tensor& residual,
    const torch::Tensor& o_proj_weight,
    torch::Tensor& output,
    cudaStream_t stream) {

    // Flatten [B, S, H] -> [B*S, H] without copying.
    const int M = static_cast<int>(attn_output.size(0) * attn_output.size(1));
    const int H = static_cast<int>(attn_output.size(2));
    // N = output hidden dim = H (o_proj_weight is square HxH).
    // K = input feature dim = H.
    const int N = H;
    const int K = H;

    auto const* A_ptr = reinterpret_cast<ElementInputA const*>(
        attn_output.data_ptr<at::BFloat16>());
    auto const* B_ptr = reinterpret_cast<ElementInputB const*>(
        o_proj_weight.data_ptr<at::BFloat16>());
    auto const* C_ptr = reinterpret_cast<ElementOutput const*>(
        residual.data_ptr<at::BFloat16>());
    auto* D_ptr = reinterpret_cast<ElementOutput*>(
        output.data_ptr<at::BFloat16>());

    CutlassGemm gemm_operator;

    CutlassGemm::Arguments args(
        {M, N, K},
        {A_ptr, K},
        {B_ptr, K},
        {C_ptr, N},   // C source = residual
        {D_ptr, N},   // D destination = output
        {1.0f, 1.0f}); // alpha = 1, beta = 1 (residual-add)

    cutlass::Status status = gemm_operator(args, nullptr, stream);
    TORCH_CHECK(
        status == cutlass::Status::kSuccess,
        "CUTLASS GEMM failed: ", cutlassGetStatusString(status));
}

#pragma once

#ifndef PROBLEM_030_ATTN_OUTPUT_PROJ_RESIDUAL_KERNEL_H
#define PROBLEM_030_ATTN_OUTPUT_PROJ_RESIDUAL_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the fused BF16 attention output projection +
// residual add kernel.
//
//   output = (attn_output @ o_proj_weight.T) + residual
//
// All BF16 contiguous. attn_output is [B, S, H]; o_proj_weight is
// [H, H]; residual is [B, S, H]; output (DPS) is [B, S, H].
// hidden_size H=2560 is pinned by the problem definition.
//
// Implemented as a 2D GEMM over the flattened M = B*S row dim with
// the CUTLASS Sm80 TensorOp BF16 template; the residual is passed
// as the C source so the epilogue does `D = α·(A·B) + β·C` with
// α=1, β=1.
void problem_030_attn_output_proj_residual_launcher(
    const torch::Tensor& attn_output,
    const torch::Tensor& residual,
    const torch::Tensor& o_proj_weight,
    torch::Tensor& output,
    cudaStream_t stream);

#endif  // PROBLEM_030_ATTN_OUTPUT_PROJ_RESIDUAL_KERNEL_H
